#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)] #[serde(rename_all = "camelCase")] pub struct GltfTopLevelMutationRejection { pub code: String, pub path: String, pub detail: String }
// 🚫️async: E1 pure codec/computation helper (file verified I/O-free, consumed via Fn-bound combinator/Display) — see R9
pub fn reject(code: impl Into<String>, path: impl Into<String>, detail: impl Into<String>) -> GltfTopLevelMutationRejection { GltfTopLevelMutationRejection { code: code.into(), path: path.into(), detail: detail.into() } }
#[derive(Clone, Copy)] pub enum GltfTopLevelFamily { Scenes, Nodes, Meshes, Accessors, BufferViews, Buffers, Materials, Textures, Images, Samplers, Skins, Animations, Cameras }
pub enum Change<'a> { Insert(usize), Delete(usize), Move(usize, usize), Reorder(&'a [usize]) }
// 🚫️async: E1 pure codec/computation helper (file verified I/O-free, consumed via Fn-bound combinator/Display) — see R9
fn remap(change: &Change<'_>, value: usize) -> Option<usize> { match change { Change::Insert(at) => Some(if value >= *at { value + 1 } else { value }), Change::Delete(at) => (value != *at).then_some(if value > *at { value - 1 } else { value }), Change::Move(from, to) => Some(if value == *from { *to } else if from < to && value > *from && value <= *to { value - 1 } else if to < from && value >= *to && value < *from { value + 1 } else { value }), Change::Reorder(order) => order.iter().position(|candidate| *candidate == value) } }
// 🚫️async: E1 pure codec/computation helper (file verified I/O-free, consumed via Fn-bound combinator/Display) — see R9
fn optional(change: &Change<'_>, value: &mut Option<usize>) { *value = value.and_then(|index| remap(change, index)); }
// 🚫️async: E1 pure codec/computation helper (file verified I/O-free, consumed via Fn-bound combinator/Display) — see R9
fn list(change: &Change<'_>, values: &mut Vec<usize>) { *values = values.iter().filter_map(|index| remap(change, *index)).collect(); }
// 🚫️async: E1 pure codec/computation helper (file verified I/O-free, consumed via Fn-bound combinator/Display) — see R9
fn required(change: &Change<'_>, value: &mut usize, path: &str) -> Result<(), GltfTopLevelMutationRejection> { *value = remap(change, *value).ok_or_else(|| reject("gltf.reference.in-use", path, "deletion would break a required typed reference"))?; Ok(()) }
