pub fn repair(document: &mut GltfDocument, family: GltfTopLevelFamily, change: &Change<'_>) -> Result<(), GltfTopLevelMutationRejection> { match family { GltfTopLevelFamily::Scenes => optional(change, &mut document.scene), GltfTopLevelFamily::Nodes => { for scene in &mut document.scenes { list(change, &mut scene.nodes); } for node in &mut document.nodes { list(change, &mut node.children); } for skin in &mut document.skins { optional(change, &mut skin.skeleton); list(change, &mut skin.joints); } for animation in &mut document.animations { for channel in &mut animation.channels { optional(change, &mut channel.target.node); } } }, GltfTopLevelFamily::Meshes => for node in &mut document.nodes { optional(change, &mut node.mesh); }, GltfTopLevelFamily::Accessors => { for mesh in &mut document.meshes { for primitive in &mut mesh.primitives { primitive.attributes = primitive.attributes.iter().filter_map(|(semantic, index)| remap(change, *index).map(|mapped| (semantic.clone(), mapped))).collect(); optional(change, &mut primitive.indices); for target in &mut primitive.targets { target.0 = target.0.iter().filter_map(|(semantic, index)| remap(change, *index).map(|mapped| (semantic.clone(), mapped))).collect(); } } } for skin in &mut document.skins { optional(change, &mut skin.inverse_bind_matrices); } for animation in &mut document.animations { for sampler in &mut animation.samplers { required(change, &mut sampler.input, "document/animations")?; required(change, &mut sampler.output, "document/animations")?; } } }, GltfTopLevelFamily::BufferViews => { for accessor in &mut document.accessors { optional(change, &mut accessor.buffer_view); if let Some(sparse) = &mut accessor.sparse { required(change, &mut sparse.indices.buffer_view, "document/accessors")?; required(change, &mut sparse.values.buffer_view, "document/accessors")?; } } for image in &mut document.images { optional(change, &mut image.buffer_view); } }, GltfTopLevelFamily::Buffers => for view in &mut document.buffer_views { required(change, &mut view.buffer, "document/bufferViews")?; }, GltfTopLevelFamily::Materials => for mesh in &mut document.meshes { for primitive in &mut mesh.primitives { optional(change, &mut primitive.material); } }, GltfTopLevelFamily::Textures => for material in &mut document.materials { if let Some(pbr) = &mut material.pbr_metallic_roughness { if let Some(info) = &mut pbr.base_color_texture { if let Some(mapped) = remap(change, info.index) { info.index = mapped; } else { pbr.base_color_texture = None; } } if let Some(info) = &mut pbr.metallic_roughness_texture { if let Some(mapped) = remap(change, info.index) { info.index = mapped; } else { pbr.metallic_roughness_texture = None; } } } if let Some(info) = &mut material.normal_texture { if let Some(mapped) = remap(change, info.index) { info.index = mapped; } else { material.normal_texture = None; } } if let Some(info) = &mut material.occlusion_texture { if let Some(mapped) = remap(change, info.index) { info.index = mapped; } else { material.occlusion_texture = None; } } if let Some(info) = &mut material.emissive_texture { if let Some(mapped) = remap(change, info.index) { info.index = mapped; } else { material.emissive_texture = None; } } }, GltfTopLevelFamily::Images => for texture in &mut document.textures { optional(change, &mut texture.source); }, GltfTopLevelFamily::Samplers => for texture in &mut document.textures { optional(change, &mut texture.sampler); }, GltfTopLevelFamily::Skins => for node in &mut document.nodes { optional(change, &mut node.skin); }, GltfTopLevelFamily::Animations => {}, GltfTopLevelFamily::Cameras => for node in &mut document.nodes { optional(change, &mut node.camera); } } Ok(()) }
macro_rules! family_ops { ($name:ident, $field:ident, $ty:ty) => { pub fn $name(snapshot: &mut GltfSnapshot, family: GltfTopLevelFamily, index: usize, position: Option<usize>, order: Option<&[usize]>) -> Result<(), GltfTopLevelMutationRejection> { let change = if let Some(order) = order { Change::Reorder(order) } else if let Some(position) = position { Change::Move(index, position) } else { Change::Delete(index) }; repair(&mut snapshot.document, family, &change)?; let values: &mut Vec<$ty> = &mut snapshot.document.$field; if let Some(order) = order { *values = order.iter().map(|index| values[*index].clone()).collect(); } else if let Some(position) = position { let value = values.remove(index); values.insert(position, value); } else { values.remove(index); } Ok(()) } }; }
family_ops!(scenes_op, scenes, GltfScene); family_ops!(nodes_op, nodes, GltfNode); family_ops!(meshes_op, meshes, GltfMesh); family_ops!(accessors_op, accessors, GltfAccessor); family_ops!(buffer_views_op, buffer_views, GltfBufferView); family_ops!(buffers_op, buffers, GltfBuffer); family_ops!(materials_op, materials, GltfMaterial); family_ops!(textures_op, textures, GltfTexture); family_ops!(images_op, images, GltfImage); family_ops!(samplers_op, samplers, GltfSampler); family_ops!(skins_op, skins, GltfSkin); family_ops!(animations_op, animations, GltfAnimation); family_ops!(cameras_op, cameras, GltfCamera);
// 🚫️async: E1 pure codec/computation helper (file verified I/O-free, consumed via Fn-bound combinator/Display) — see R9
pub fn family_diff(_family: GltfTopLevelFamily, base: &GltfSnapshot, next: &GltfSnapshot) -> GltfDiff { let scenes = GltfScenesDiff::between(&base.document.scenes, &next.document.scenes); let nodes = GltfNodesDiff::between(&base.document.nodes, &next.document.nodes); let meshes = GltfMeshesDiff::between(&base.document.meshes, &next.document.meshes); let accessors = GltfAccessorsDiff::between(&base.document.accessors, &next.document.accessors); let buffer_views = GltfBufferViewsDiff::between(&base.document.buffer_views, &next.document.buffer_views); let buffers = GltfBuffersDiff::between(&base.document.buffers, &next.document.buffers); let bytes = GltfBufferBytesDiff::between(&base.buffers, &next.buffers); let materials = GltfMaterialsDiff::between(&base.document.materials, &next.document.materials); let textures = GltfTexturesDiff::between(&base.document.textures, &next.document.textures); let images = GltfImagesDiff::between(&base.document.images, &next.document.images); let samplers = GltfSamplersDiff::between(&base.document.samplers, &next.document.samplers); let skins = GltfSkinsDiff::between(&base.document.skins, &next.document.skins); let animations = GltfAnimationsDiff::between(&base.document.animations, &next.document.animations); let cameras = GltfCamerasDiff::between(&base.document.cameras, &next.document.cameras); GltfDiff { scene: (base.document.scene != next.document.scene).then_some(next.document.scene), scenes: (!scenes.is_empty()).then_some(scenes), nodes: (!nodes.is_empty()).then_some(nodes), meshes: (!meshes.is_empty()).then_some(meshes), accessors: (!accessors.is_empty()).then_some(accessors), buffer_views: (!buffer_views.is_empty()).then_some(buffer_views), buffers: (!buffers.is_empty()).then_some(buffers), buffer_bytes: (!bytes.is_empty()).then_some(bytes), materials: (!materials.is_empty()).then_some(materials), textures: (!textures.is_empty()).then_some(textures), images: (!images.is_empty()).then_some(images), samplers: (!samplers.is_empty()).then_some(samplers), skins: (!skins.is_empty()).then_some(skins), animations: (!animations.is_empty()).then_some(animations), cameras: (!cameras.is_empty()).then_some(cameras), ..Default::default() } }
